            { "hud.checkpoint.log",  ("The ship was returned to a checkpoint during the cruise.", "La nave volvió a un punto de control durante el crucero.") },
            { "free.time",     ("FREE", "LIBRE") },
            { "free.near",     ("Near {0}", "Cerca de {0}") },
            { "free.logbook",  ("LOGBOOK {0}/{1} · scan everything you find", "BITÁCORA {0}/{1} · escanea todo lo que encuentres") },
            { "free.welcome",  ("FREE FLIGHT\nThe planets are where they really are today. Explore, scan, meet your friends.", "VUELO LIBRE\nLos planetas están donde están hoy de verdad. Explora, escanea, encuentra a tus amigos.") },
            { "free.invite",   ("{0} is exploring the Solar System: tap EXPLORE to join", "{0} está explorando el Sistema Solar: toca EXPLORAR para unirte") },
            { "free.respawn",  ("Hull lost! Back at Earth with a new ship", "¡Casco perdido! De vuelta en la Tierra con una nave nueva") },
            { "free.sun",      ("Too close to the Sun!", "¡Demasiado cerca del Sol!") },
            { "scan.logbook",  ("NEW IN YOUR LOGBOOK", "NUEVO EN TU BITÁCORA") },
            { "scan.sun.t",    ("The Sun", "El Sol") },
            { "scan.sun",      ("Our star holds 99.8% of the Solar System's mass. Its light takes about 8 minutes 20 seconds to reach Earth. NASA's Parker Solar Probe has flown closer to it than any spacecraft ever.", "Nuestra estrella tiene el 99,8% de la masa del Sistema Solar. Su luz tarda unos 8 minutos y 20 segundos en llegar a la Tierra. La sonda Parker de la NASA se ha acercado más que cualquier otra nave.") },
            { "scan.moon.luna.t", ("The Moon", "La Luna") },
            { "scan.moon.luna",   ("Earth's Moon, 384,400 km away. Twelve astronauts walked on it during Apollo (1969-1972), and NASA's Artemis program will take people back.", "La Luna de la Tierra, a 384.400 km. Doce astronautas caminaron sobre ella con Apolo (1969-1972), y el programa Artemis de la NASA llevará personas de nuevo.") },
            // ── Hangar ────────────────────────────────────────────────────────
            { "hangar.button",  ("SHIP", "NAVE") },
            { "hangar.title",   ("HANGAR", "HANGAR") },
            { "hangar.choose",  ("FLY THIS SHIP", "VOLAR ESTA NAVE") },
            { "hangar.current", ("current", "actual") },
            { "hangar.note",    ("Looks only: speed, fuel and ΔV come from your mission design, not the hull.", "Solo es el aspecto: la velocidad, el combustible y el ΔV vienen de tu diseño de misión, no del casco.") },
            { "ship.1.name",  ("Navigator", "Navigator") },
            { "ship.1.desc",  ("The original explorer of the project: balanced, reliable, ready for any world.", "La exploradora original del proyecto: equilibrada, confiable, lista para cualquier mundo.") },
            { "ship.2.name",  ("Kronos", "Kronos") },
            { "ship.2.desc",  ("The rival's hull: dark and aggressive.", "El casco del rival: oscuro y agresivo.") },
            { "ship.3.name",  ("Launcher", "Lanzador") },
            { "ship.3.desc",  ("Fly the whole rocket, stages and all.", "Vuela el cohete completo, con todas sus etapas.") },
            { "ship.4.name",  ("Supply Capsule", "Cápsula de suministros") },
            { "ship.4.desc",  ("A compact cargo capsule: small, tough and hard to hit.", "Una cápsula de carga compacta: pequeña, resistente y difícil de alcanzar.") },
            { "ship.5.name",  ("Orion", "Orión") },
            { "ship.5.desc",  ("Inspired by NASA's Orion, the capsule of the Artemis missions to the Moon, with its service module.", "Inspirada en Orion de la NASA, la cápsula de las misiones Artemis a la Luna, con su módulo de servicio.") },
            { "ship.6.name",  ("Interplanetary Cruiser", "Crucero interplanetario") },
            { "ship.6.desc",  ("Long hull and ion engine, like deep-space probes such as Dawn.", "Casco largo y motor iónico, como las sondas de espacio profundo tipo Dawn.") },
            { "ship.7.name",  ("Space Apps Racer", "Corredora Space Apps") },
            { "ship.7.desc",  ("Orange and white racer wearing a mission patch.", "Corredora naranja y blanca con parche de misión.") },
            { "ship.8.name",  ("Soyuz-inspired", "Inspirada en Soyuz") },
            { "ship.8.desc",  ("Orbital module plus descent capsule, like the Soyuz that has flown crews since 1967.", "Módulo orbital más cápsula de descenso, como la Soyuz que lleva tripulaciones desde 1967.") },
            { "ship.9.name",  ("Shuttle-inspired", "Inspirada en el transbordador") },
            { "ship.9.desc",  ("A white delta wing like the Space Shuttle, which flew 135 missions from 1981 to 2011.", "Ala delta blanca como el transbordador espacial, que voló 135 misiones de 1981 a 2011.") },
            { "ship.10.name", ("Stealth Manta", "Manta sigilosa") },
            { "ship.10.desc", ("Flat black hull with a bioluminescent blue stripe.", "Casco plano negro con una franja azul bioluminiscente.") },
            // ── Credits ───────────────────────────────────────────────────────
            { "credits.button", ("CREDITS", "CRÉDITOS") },
            { "credits.title",  ("CREDITS", "CRÉDITOS") },
            { "credits.body",   ("<b>Navigator</b> · NASA Space Apps Challenge 2026 · Guacalita Inc.\n\n<b><color=#33CCFF>NASA DATA</color></b>\nReal-time planet positions: NASA/JPL Horizons System.\nMission facts, ΔV, orbit insertions, probes, planets and moons: NASA Science and NASA/JPL mission pages.\nGravity-assist routes: MESSENGER, Galileo, Cassini and Voyager 2 (NASA/JPL).\n\n<b><color=#33CCFF>SKY IMAGES</color></b>\nOrion Nebula: NASA, ESA, M. Robberto (STScI/ESA), Hubble Orion Treasury Project Team.\nHelix Nebula: NASA/JPL-Caltech (Spitzer).\nPillars of Creation: NASA, ESA, Hubble Heritage Team (STScI/AURA).\nRing Nebula: NASA, ESA, Hubble Heritage (STScI/AURA)-ESA/Hubble Collaboration (CC BY 4.0).\nWhirlpool Galaxy (M51): NASA, ESA, S. Beckwith (STScI), Hubble Heritage Team.\nHubble Deep Field South: NASA, ESA, HDF-S team (STScI).\nM87* black hole: Event Horizon Telescope Collaboration (CC BY 4.0).\nCarina Nebula, Horsehead Nebula and Andromeda: Wikimedia Commons (authors and licenses in CREDITS.md).\n\n<b><color=#33CCFF>3D MODELS</color></b>\nGenerated with Meshy AI.\n\n<b><color=#33CCFF>SOFTWARE</color></b>\nUnity 6 · glTFast (Apache 2.0) · ZXing.Net (Apache 2.0) · flutter_embed_unity (MIT) · Flutter · Iroh P2P (MIT/Apache 2.0) · Liberation Sans (SIL OFL).\nAll sounds are synthesized in code.", "<b>Navigator</b> · NASA Space Apps Challenge 2026 · Guacalita Inc.\n\n<b><color=#33CCFF>DATOS DE LA NASA</color></b>\nPosición real de los planetas: sistema Horizons de NASA/JPL.\nDatos de misiones, ΔV, inserciones orbitales, sondas, planetas y lunas: NASA Science y páginas de misiones de NASA/JPL.\nRutas con asistencia gravitatoria: MESSENGER, Galileo, Cassini y Voyager 2 (NASA/JPL).\n\n<b><color=#33CCFF>IMÁGENES DEL CIELO</color></b>\nNebulosa de Orión: NASA, ESA, M. Robberto (STScI/ESA), Hubble Orion Treasury Project Team.\nNebulosa de la Hélice: NASA/JPL-Caltech (Spitzer).\nPilares de la Creación: NASA, ESA, Hubble Heritage Team (STScI/AURA).\nNebulosa del Anillo: NASA, ESA, Hubble Heritage (STScI/AURA)-ESA/Hubble Collaboration (CC BY 4.0).\nGalaxia del Remolino (M51): NASA, ESA, S. Beckwith (STScI), Hubble Heritage Team.\nCampo Profundo Sur del Hubble: NASA, ESA, equipo HDF-S (STScI).\nAgujero negro M87*: Event Horizon Telescope Collaboration (CC BY 4.0).\nNebulosa de Carina, Cabeza de Caballo y Andrómeda: Wikimedia Commons (autores y licencias en CREDITS.md).\n\n<b><color=#33CCFF>MODELOS 3D</color></b>\nGenerados con Meshy AI.\n\n<b><color=#33CCFF>SOFTWARE</color></b>\nUnity 6 · glTFast (Apache 2.0) · ZXing.Net (Apache 2.0) · flutter_embed_unity (MIT) · Flutter · Iroh P2P (MIT/Apache 2.0) · Liberation Sans (SIL OFL).\nTodos los sonidos se sintetizan en código.") },
